use vstd::prelude::*;

verus! {

/// Given an 8-bit signed integer n ≥ 2, returns
/// - "black\n"        if n is odd,
/// - "white\n1 2\n"  if n is even.
fn solve(n: i8) -> (result: String)
    requires
        n >= 2,
    ensures
        // Exactly one of the two outcomes, matching the parity of n,
        (n % 2 == 1 && result == String::from_str("black\n"))
        ||
        (n % 2 == 0 && result == String::from_str("white\n1 2\n"))
{
    if n % 2 == 1 {
        // odd case
        String::from_str("black\n")
    } else {
        // even case
        String::from_str("white\n1 2\n")
    }
}

}

